from collections import deque
BG=None
def transform(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    # background = most common color
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]
                # BFS the shape's cells? Instead: flood fill background-ish region enclosed by shape.
                # Simpler: find connected component of color c bounding box; hole = cells inside bbox not color c and connected component of non-c enclosed.
                q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[y for y,_ in cells]; xs=[x for _,x in cells]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                if y1-y0<2 or x1-x0<2: continue
                # hole cells: inside bbox, not color c; find connected components of non-c within bbox not touching bbox border? Hole = components not containing bbox-edge-adjacent outside... simpler: components of non-c cells within bbox that don't touch bbox boundary ring outside — use: components of non-c within bbox; those that don't include a cell on bbox perimeter with a path out. Easiest: flood from bbox border inward over non-c cells; remaining non-c cells inside are holes.
                hole=[[False]*W for _ in range(H)]
                dq=deque()
                for x in range(x0,x1+1):
                    for y in (y0,y1):
                        if g[y][x]!=c and not hole[y][x]: hole[y][x]=True; dq.append((y,x))
                for y in range(y0,y1+1):
                    for x in (x0,x1):
                        if g[y][x]!=c and not hole[y][x]: hole[y][x]=True; dq.append((y,x))
                while dq:
                    y,x=dq.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if y0<=ny<=y1 and x0<=nx<=x1 and g[ny][nx]!=c and not hole[ny][nx]:
                            hole[ny][nx]=True; dq.append((ny,nx))
                hcells=[(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if g[y][x]!=c and not hole[y][x]]
                if not hcells: continue
                hy=[y for y,_ in hcells]; hx=[x for _,x in hcells]
                hh,hw=max(hy)-min(hy)+1, max(hx)-min(hx)+1
                fill=7 if (hh%2==1 and hw%2==1) else 2
                for y,x in hcells: out[y][x]=fill
    return out

